lookup.day_rate:
// Decree 145/2020 art.54(1)(a)(a3): a day of a monthly wage is the wage over the month's normal working days, so proration_basis is WORKING_DAYS. Art.55 and Labour Code 45/2019/QH14 art.98 price overtime on the same day.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const amount = Number(get(terms, 'rate.amount', 0));
const from = month_start(ctx.run.salary_coverage.from);
const to = month_end(ctx.run.salary_coverage.from);
const offDays = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
let workingDays = 0;
for (let day = from; day <= to; day = add_days(day, 1)) {
	if (!offDays.includes(weekday(day))) workingDays = workingDays + 1;
}
const weekDays = Math.max(1, 7 - offDays.length);
const contractDays = Number(get(terms, 'normal_days_per_week', 0)) || weekDays;
const days =
	workingDays > 0 ? (workingDays * contractDays) / weekDays : ctx.lookup.fallback_working_days;
const fixed = Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0));
const hours = Number(get(terms, 'normal_hours_per_day', 0)) || ctx.lookup.normal_hours_per_day;
if (unit === 'HOURLY') return (amount * days * hours + fixed) / days;
if (unit === 'DAILY') return (amount * days + fixed) / days;
return (amount + fixed) / days;
